{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Octreotide, a cyclic peptide, had absolute oral bioavailability of only 0.6 ± 0.4% in healthy volunteers after oral capsule dosing, demonstrating that cyclic peptide scaffolds with multiple amide bonds and polar groups can have very low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Colistin, a cyclic peptide, is reported to have low and virtually negligible oral bioavailability in patients, supporting poor oral absorption for polar cyclic peptide-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Acamprosate, a small highly polar and ionized molecule with amide and sulfonate groups, has absolute oral bioavailability of only 11 ± 1% in humans, supporting low F for highly polar, ionized molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Polymyxin B, a cyclic peptide, is not used orally due to poor bioavailability, reinforcing the pattern that cyclic peptide/polar ionizable structures tend to have low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Microcystin-LR, a cyclic peptide with multiple polar groups, is indicated to have low oral bioavailability in humans, consistent with the query's polar cyclic peptide-like character.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a highly polar, fully ionized cyclic dipeptide-like dicarboxylic acid with multiple amide groups and very low predicted lipophilicity. The most transferable experimental evidence—cyclic peptides and small polar ionized drugs—consistently shows low oral bioavailability (octreotide 0.6%, colistin negligible, acamprosate 11%, polymyxin B poor, microcystin-LR low). No structurally close high-bioavailability analogue outweighs this pattern, so the prediction is low oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data exist for this exact diketopiperazine dicarboxylate scaffold.",
    "Morgan similarities to available evidence are low, limiting quantitative transferability.",
    "Possible active uptake, transporter effects, or prodrug-like behavior are not experimentally ruled out.",
    "No permeability, efflux, or solubility measurements are available for the query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

